const picker = document.querySelector('.language-picker');
const menu = document.querySelector('.language-menu');
const toggle = document.querySelector('.language-toggle');
const storedLanguage = localStorage.getItem('lylo-site-language') || localStorage.getItem('lylo-language') || 'es';
const accountMenu = document.querySelector('[data-account-menu]');
const loginLink = document.querySelector('[data-login-link]');
const accountToggle = document.querySelector('.account-toggle');
const accountDropdown = document.querySelector('.account-dropdown');
const accountAvatarElements = document.querySelectorAll('[data-account-avatar]');
const accountName = document.querySelector('[data-account-name]');
const manageServersButton = document.querySelector('[data-manage-servers]');
const defaultAvatar = 'BOTIMAGEN.png';

function renderMenu(currentCode) {
  menu.innerHTML = languages.map((language) => `<button class="language-option ${language.code === currentCode ? 'selected' : ''}" role="menuitem" type="button" data-language="${language.code}"><span>${language.flag}</span><span>${language.label}</span></button>`).join('');
  menu.querySelectorAll('.language-option').forEach((option) => option.addEventListener('click', () => setLanguage(option.dataset.language)));
}

function applySiteLanguage(code) {
  const language = languages.find((item) => item.code === code) || languages[2];
  const copy = { ...completeTranslations.es, ...translations[language.code], ...completeTranslations[language.code], ...legalTranslations[language.code], ...sharedTranslations[language.code], ...accessibilityTranslations[language.code] };
  document.documentElement.lang = language.code;
  document.querySelectorAll('[data-i18n]').forEach((element) => { if (copy[element.dataset.i18n]) element.textContent = copy[element.dataset.i18n]; });
  document.querySelectorAll('[data-i18n-placeholder]').forEach((element) => { if (copy[element.dataset.i18nPlaceholder]) element.placeholder = copy[element.dataset.i18nPlaceholder]; });
  document.querySelectorAll('[data-i18n-title]').forEach((element) => { if (copy[element.dataset.i18nTitle]) element.title = copy[element.dataset.i18nTitle]; });
  document.querySelectorAll('[data-i18n-aria-label]').forEach((element) => { if (copy[element.dataset.i18nAriaLabel]) element.setAttribute('aria-label', copy[element.dataset.i18nAriaLabel]); });
  const pageTitle = document.querySelector('title[data-i18n]');
  if (pageTitle && copy[pageTitle.dataset.i18n]) pageTitle.textContent = copy[pageTitle.dataset.i18n];
  const currentFlag = document.querySelector('.current-flag');
  const currentLanguage = document.querySelector('.current-language');
  if (currentFlag) currentFlag.textContent = language.flag;
  if (currentLanguage) currentLanguage.textContent = language.code.toUpperCase();
  if (menu) renderMenu(language.code);
}

function setLanguage(code) {
  const language = languages.find((item) => item.code === code) || languages[2];
  applySiteLanguage(language.code);
  localStorage.setItem('lylo-site-language', language.code);
  document.dispatchEvent(new CustomEvent('lylo-language-change', { detail: language.code }));
  if (picker) picker.classList.remove('open');
  if (toggle) toggle.setAttribute('aria-expanded', 'false');
}

