window.lyloTranslate = (key, code = document.documentElement.lang) => languageResetCopy[code]?.[key] || sharedTranslations[code]?.[key] || sharedTranslations.es[key] || key;
document.addEventListener('lylo-language-change', (event) => applySiteLanguage(event.detail));
document.addEventListener('lylo-language-change', (event) => {
  const copy = languageResetCopy[event.detail] || languageResetCopy.es;
  document.querySelectorAll('[data-i18n]').forEach((element) => {
    if (copy[element.dataset.i18n]) element.textContent = copy[element.dataset.i18n];
  });
});

if (toggle && picker) {
  toggle.addEventListener('click', () => { const open = picker.classList.toggle('open'); toggle.setAttribute('aria-expanded', String(open)); });
  document.addEventListener('click', (event) => { if (!picker.contains(event.target)) { picker.classList.remove('open'); toggle.setAttribute('aria-expanded', 'false'); } });
}

function renderAccount(user) {
  if (manageServersButton) manageServersButton.hidden = !user;
  if (!accountMenu) return;
  if (!user) {
    loginLink.hidden = false;
    accountToggle.hidden = true;
    accountDropdown.hidden = true;
    return;
  }
  loginLink.hidden = true;
  accountToggle.hidden = false;
  accountAvatarElements.forEach((image) => { image.src = user.avatar || defaultAvatar; image.alt = user.username || 'Discord account'; });
  accountName.textContent = user.username || 'Discord user';
}

if (accountToggle) {
  accountToggle.addEventListener('click', () => {
    const isOpen = !accountDropdown.hidden;
    accountDropdown.hidden = isOpen;
    accountToggle.setAttribute('aria-expanded', String(!isOpen));
  });
  document.querySelector('[data-logout]').addEventListener('click', () => {
    fetch('/auth/logout', { method: 'POST' }).finally(() => {
      accountDropdown.hidden = true;
      accountToggle.setAttribute('aria-expanded', 'false');
      renderAccount(null);
    });
  });
  document.addEventListener('click', (event) => {
    if (!accountMenu.contains(event.target)) {
      accountDropdown.hidden = true;
      accountToggle.setAttribute('aria-expanded', 'false');
    }
  });
}

setLanguage(storedLanguage);
fetch('/api/me').then((response) => response.json()).then(({ user }) => renderAccount(user)).catch(() => renderAccount(null));

const revealObserver = window.matchMedia('(prefers-reduced-motion: reduce)').matches || !('IntersectionObserver' in window)
  ? null
  : new IntersectionObserver((entries, observer) => {
    entries.forEach((entry) => {
      if (!entry.isIntersecting) return;
      entry.target.classList.add('is-visible');
      observer.unobserve(entry.target);
    });
  }, { rootMargin: '0px 0px -8% 0px', threshold: 0.12 });

function revealVisibleElements() {
  const visibleTop = window.innerHeight * 0.92;
  const visibleBottom = window.innerHeight * 0.08;
  document.querySelectorAll('.scroll-reveal:not(.is-visible)').forEach((element) => {
    const bounds = element.getBoundingClientRect();
    if (bounds.top < visibleTop && bounds.bottom > visibleBottom && bounds.left < window.innerWidth && bounds.right > 0) {
      element.classList.add('is-visible');
    }
  });
}

function observeScrollReveals() {
  if (!revealObserver) return;
  const revealTargets = document.querySelectorAll('main > section, .hero-reference-content, .feature-item, .plan-card, .premium-hero, .premium-footnote, .manage-heading, .server-search, .server-state, .server-card, .config-heading, .config-note, .config-section, .config-preview, .language-heading, .language-section, .language-reset-warning, .legal-page > .eyebrow, .legal-page > h1, .legal-page > h2, .legal-page > p, .legal-page > .back-link, .error-content > *');
  revealTargets.forEach((element, index) => {
    if (element.classList.contains('scroll-reveal')) return;
    element.classList.add('scroll-reveal');
    element.style.setProperty('--reveal-delay', `${Math.min(index % 7, 6) * 75}ms`);
    if (element.matches('.feature-item, .plan-card, .server-card, .config-section')) element.style.setProperty('--reveal-x', index % 2 ? '18px' : '-18px');
    revealObserver.observe(element);
  });
  revealVisibleElements();
}

observeScrollReveals();
window.addEventListener('scroll', revealVisibleElements, { passive: true });
window.addEventListener('resize', revealVisibleElements);
document.addEventListener('visibilitychange', revealVisibleElements);
if (revealObserver && document.body) {
  new MutationObserver((records) => {
    if (records.some((record) => record.addedNodes.length)) observeScrollReveals();
  }).observe(document.body, { childList: true, subtree: true });
}

const communitiesGrid = document.querySelector('[data-communities-grid]');
const communityEmpty = document.querySelector('[data-community-empty]');
const communityLogo = 'https://cdn.discordapp.com/embed/avatars/0.png';

function escapeHtml(value) {
  return String(value).replace(/[&<>'"]/g, (character) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', "'": '&#39;', '"': '&quot;' })[character]);
}

function renderCommunities(communities) {
  if (!communitiesGrid) return;
  if (!communities.length) {
    communitiesGrid.innerHTML = '';
    communityEmpty.hidden = false;
    communitiesGrid.appendChild(communityEmpty);
    return;
  }
  communityEmpty.hidden = true;
  const membersLabel = (communityTranslations[document.documentElement.lang] || communityTranslations.es).communityMembers;
  const cards = communities.map((community) => `<article class="community-card"><img src="${community.icon || communityLogo}" alt="${escapeHtml(community.name)}"><div><h3>${escapeHtml(community.name)}</h3><p>${Number(community.memberCount).toLocaleString(document.documentElement.lang)} <span>${membersLabel}</span></p></div></article>`).join('');
  communitiesGrid.innerHTML = cards + cards;
}

async function loadCommunities() {
  if (!communitiesGrid) return;
  try {
    const response = await fetch('/api/communities');
    const data = await response.json();
    renderCommunities(data.communities || []);
  } catch {
    renderCommunities([]);
  }
}

loadCommunities();
document.addEventListener('lylo-language-change', loadCommunities);
window.setInterval(loadCommunities, 5000);
